const input = $input.first().json;
const body = input.body || input;
const inboundText = String(body.inbound_text || body.body_text || body.Body || input.inbound_text || input.body_text || input.Body || 'Hi, I am interested in your product');
const lowered = inboundText.toLowerCase();
const infoKeywords = [
  'policy', 'return', 'refund', 'faq', 'how', 'what is', 'what are', 'support',
  '\u9000\u8d27', '\u9000\u6b3e', '\u653f\u7b56', '\u5e38\u89c1\u95ee\u9898', '\u600e\u4e48', '\u5982\u4f55', '\u662f\u4ec0\u4e48'
];
const isInformationQuery = infoKeywords.some((keyword) => lowered.includes(keyword));
return [{
  json: {
    customer_id: body.customer_id || input.customer_id || '11111111-1111-4111-8111-111111111111',
    customer_phone: body.customer_phone || input.customer_phone || '+15551234567',
    customer_display_name: body.customer_display_name || input.customer_display_name || 'Demo Buyer',
    message_id: body.message_id || input.message_id || '22222222-2222-4222-8222-222222222222',
    inbound_text: inboundText,
    intent: body.intent || input.intent || (isInformationQuery ? 'information_query' : 'purchase'),
    intent_confidence: body.intent_confidence || body.confidence || input.intent_confidence || input.confidence || (isInformationQuery ? 0.88 : 0.91),
    ticket_id: body.ticket_id || input.ticket_id || 'TICKET-PHASE1A-001',
    route_intent: isInformationQuery ? 'rag' : 'sales',
  },
}];

const input = $input.first().json || {};
const hasAnswer = typeof input.answer === 'string' && input.answer.trim().length > 0;
const hasError = Boolean(input.error || input.message === 'Connection refused' || input.name === 'NodeApiError');
if (!hasAnswer || hasError) {
  return [{
    json: {
      action: 'reply',
      reply_text: 'Sorry, the knowledge service is temporarily unavailable. Please try again later.',
      fallback: true,
      route_intent: 'rag',
      error_message: input.error?.message || input.message || 'rag_api_unavailable'
    }
  }];
}
return [{ json: input }];

const input = $input.first().json || {};
const hasReply = typeof input.reply_text === 'string' && input.reply_text.trim().length > 0;
const hasError = Boolean(input.error || input.message === 'Connection refused' || input.name === 'NodeApiError');
if (!hasReply || hasError) {
  return [{
    json: {
      action: 'reply',
      reply_text: 'Sorry, the sales assistant is temporarily unavailable. Please try again later.',
      conversation_stage: 'fallback',
      lead_score: null,
      qualification_tier: 'unknown',
      handoff_triggered: false,
      fallback: true,
      route_intent: 'sales',
      error_message: input.error?.message || input.message || 'sales_agent_unavailable'
    }
  }];
}
return [{ json: input }];
